    /** Tier classifies momentum: SINK below zero, STEADY up to 199, SURGE from 200; absent with momentum. */
    public String getTier() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        return momentum < 0 ? "SINK" : momentum <= 199 ? "STEADY" : "SURGE";
    }

    /** Band classifies adjusted: E below 0, D up to 49, C up to 149, B up to 299, A from 300; absent with adjusted. */
    public String getBand() {
        Integer adjusted = getAdjusted();
        if (adjusted == null) {
            return null;
        }
        return adjusted < 0 ? "E" : adjusted <= 49 ? "D" : adjusted <= 149 ? "C" : adjusted <= 299 ? "B" : "A";
    }
}
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma,
            Grade grade, Integer weight, Integer thrust, Integer drift, Integer momentum, Integer load, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile, LocalDate onset, Long age, Long decay, boolean active, Integer effective,
            Integer clout, Integer influence, List<String> regions, Integer reach,
            List<PatronView> allies, int allyCount, Integer synergy, Integer combined, Integer score, int noteSum, Integer quality, Integer adjusted, String band) {
        static PersonView of(Person p, Map<Long, Integer> ranks, LocalDate anchor) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(),
                    p.getGrade(), p.getWeight(), p.getThrust(), p.getDrift(), p.getMomentum(), p.getLoad(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()), p.getOnset(),
                    p.getAge(anchor), p.getDecay(anchor), p.isActive(), p.getEffective(), p.getClout(),
                    p.getInfluence(), p.getRegions(), p.getReach(),
                    p.getAllies().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getAllies().size(), p.getSynergy(), p.getCombined(), p.getScore(), p.getNoteSum(), p.getQuality(), p.getAdjusted(), p.getBand());
        }
    }

    /**
     * A rank as a percentile of the ranked people: the best 100, the worst 0, evenly spread between
  regions: string[];
  reach: number | null;
  allies: Ally[];
  allyCount: number;
  synergy: number | null;
  combined: number | null;
  score: number | null;
  noteSum: number;
  quality: number | null;
  adjusted: number | null;
  band: string | null;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {
  id: string | null;
// Their reach is the sum, over their regions, of momentum times the region's multiplier, from its first
// letter: N 2, S 3, any other 1 ("n/a" while momentum is missing or they have no region).
// The sheet's region counts show, for each region its people have, how many of them are in it
// (a person counts once in every region they belong to), ordered by region code.
// Each person may follow any number of other people, chosen on the row; following is one-directional,
// so A following B does not make B follow A. A person's allies are the people they follow, listed by name, with how many there are,
// and their synergy: the allies' thrust added together (zero without allies).
// Their combined is their influence plus their synergy ("n/a" while either is "n/a").
// Each person may have a single whole-number score, set on the row. Their note sum is their score (zero
// without one) and their quality is their score ("n/a" without one).
// Their adjusted is their combined plus their quality, counting quality as zero without a score ("n/a" while
// combined is "n/a").
// Their band classifies their adjusted: E below 0, D from 0 to 49, C from 50 to 149, B from 150 to 299 and
// A from 300 ("n/a" while adjusted is "n/a").
